Default content:
{%- liquid
  if request.locale.iso_code == 'en'
    assign brand_alternate_names = "NATURE MAGIC Pet Food" | split: '|'
  else
    assign brand_alternate_names = "自然魔法|自然魔法寵物" | split: '|'
  endif

  assign brand_alternate_names_json = brand_alternate_names | json
-%}

{% comment %} Breadcrumb label {% endcomment %}
{%- liquid
  if request.locale.iso_code == 'en'
    assign breadcrumb_home_label = 'Home'
  else
    assign breadcrumb_home_label = '首頁'
  endif
-%}

{% comment %} 圖片選擇邏輯 {% endcomment %}
{%- liquid
  assign structured_seo_image = shop.brand.cover_image | default: settings.logo

  if structured_seo_image == blank
    assign structured_seo_image = settings.share_image
  endif

  if structured_seo_image == blank
    assign structured_seo_image = settings.logo
  endif

  assign website_image = structured_seo_image

  if template == 'index'
    if shop.brand.cover_image
      assign website_image = shop.brand.cover_image
    elsif settings.share_image
      assign website_image = settings.share_image
    else
      assign website_image = structured_seo_image
    endif

  elsif template contains 'collection' and collection and collection.image
    assign website_image = collection.image

  elsif template contains 'product' and product and product.featured_image
    assign website_image = product.featured_image

  elsif template contains 'article' and article and article.image
    assign website_image = article.image

  elsif template contains 'page' and page and page.image
    assign website_image = page.image
  endif

  if website_image == blank
    assign website_image = settings.logo
  endif
-%}

{% comment %} SEO Title &amp; Description {% endcomment %}
{%- liquid
  assign seo_title = page_title
  assign seo_description = page_description
  assign homepage_name_override = blank
  assign homepage_description_override = blank

  if template == 'index'
    if request.locale.iso_code == 'en' and seo_title == 'NATURE MAGIC'
      assign seo_title = "NATURE MAGIC HK Official Site | Natural Pet Food from New Zealand"
    endif

    if request.locale.iso_code == 'zh' and seo_title == 'NATURE MAGIC'
      assign seo_title = "NATURE MAGIC 香港官方網站 | 紐西蘭天然寵物食品"
    endif

    assign homepage_name_override = seo_title
    assign homepage_description_override = seo_description
  endif
-%}

<script type="application/ld+json">
{
