          "description": "{{ metaobjects.certification.mpi.issuing_body.value }}",
          "certificationIdentification": "MPI"
        }
        {%- assign cert_comma = true -%}
        {% endif %}
        {% if metaobjects.certification.fda %}
        {% if cert_comma %},{% endif %}
        {
          "@type": "Certification",
          "name": "{{ metaobjects.certification.fda.name.value }}",
          "description": "{{ metaobjects.certification.fda.issuing_body.value }}",
