          "description": "{{ metaobjects.certification.haccp.issuing_body.value }}",
          "certificationIdentification": "HACCP"
        }
        {%- assign cert_comma = true -%}
        {% endif %}
        {% if metaobjects.certification.ce %}
        {% if cert_comma %},{% endif %}
        {
          "@type": "Certification",
          "name": "{{ metaobjects.certification.ce.name.value }}",
          "description": "{{ metaobjects.certification.ce.issuing_body.value }}",
          "certificationIdentification": "CE"
        }
        {%- assign cert_comma = true -%}
        {% endif %}
        {% if metaobjects.certification.fern-mark %}
