          "description": "專業寵物食品批發服務，歡迎零售商、寵物店、獸醫診所等業務合作夥伴洽談"
        },
        {
          "@type": "Organization", 
          "name": "線上零售部門",
          "description": "提供完整的線上購物體驗，包括產品諮詢、快速配送等服務"
        },
        {
          "@type": "Organization",
          "name": "HKTVmall",
          "@id": "https://naturemagic.com.hk#hktvmall",
          "url": "https://www.hktvmall.com/hktv/zh/main/NATURE-MAGIC-%E5%AE%98%E6%96%B9%E6%97%97%E8%89%A6%E5%BA%97/s/B1527001"
        },
        {
          "@type": "Organization", 
          "name": "The Place",
          "@id": "https://naturemagic.com.hk#theplace",
          "url": "https://www.theplace.shop/naturemagic"
        }
      ]
    },
    {
      "@type": "LocalBusiness",
      "@id": "{{ shop.url }}#localbusiness",
      "name": "NATURE MAGIC 旗艦店",
      "url": "{{ shop.url }}",
      "telephone": "+852 5715 2657",
      "email": "mailto:service@naturemagic.com.hk",
      "priceRange": "$20-$300",
      "contactPoint": {
        "@type": "ContactPoint",
        "contactType": "Customer Service",
        "availableLanguage": ["Chinese", "English"],
        "telephone": "+852 5715 2657",
        "email": "mailto:service@naturemagic.com.hk"
      },
      "address": {
        "@type": "PostalAddress",
        "addressCountry": "HK",
        "addressRegion": "Hong Kong",
        "addressLocality": "North Point",
        "streetAddress": "RM A, 19/F Max Share Ctr, 367-373 King's Rd",
        "postalCode": "999077"
      },
      "geo": {
        "@type": "GeoCoordinates",
        "latitude": 22.291,
        "longitude": 114.200
      },
      "openingHoursSpecification": [
        {
          "@type": "OpeningHoursSpecification",
          "dayOfWeek": ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"],
          "opens": "09:00",
          "closes": "18:00"
        }
      ],
      {% if settings.logo %}
      "image": {
        "@type": "ImageObject",
        "url": "{{ settings.logo | image_url: width: 1200 | prepend: 'https:' }}",
        "width": 1200,
        "height": 630,
        "caption": "NATURE MAGIC LOGO"
      },
      {% endif %}
      "makesOffer": [
        {
          "@type": "Offer",
          "description": "香港本地寵物食品零售與批發服務",
          "category": "本地零售業務",
          "areaServed": "Hong Kong",
          "businessFunction": "http://purl.org/goodrelations/v1#Sell"
        },
        {
          "@type": "Offer",
          "description": "專業寵物營養諮詢與客戶服務",
          "category": "諮詢服務", 
          "areaServed": "Hong Kong",
          "businessFunction": "http://purl.org/goodrelations/v1#ProvideService"
        }
