    },
    {
      "@type": "WebSite",
      "@id": "{{ shop.url }}#website",
      "url": "{{ shop.url }}",
      "name": {{ homepage_name_override | default: shop.name | json }}
      {% if homepage_description_override != blank %}
      ,
      "description": {{ homepage_description_override | strip_html | strip_newlines | json }}
      {% elsif shop.description != blank %}
      ,
      "description": {{ shop.description | strip_html | strip_newlines | json }}
      {% endif %}
      ,
      "inLanguage": "{{ request.locale.iso_code }}",
      "publisher": {
        "@id": "{{ shop.url }}#organization"
      }
      {% if website_image %}
      ,
      "image": {
        "@type": "ImageObject",
        "url": "{{ website_image | image_url: width: 1200 | prepend: 'https:' }}",
        "width": 1200,
        "height": 630
      }
      {% endif %}
      ,
      "potentialAction": {
        "@type": "SearchAction",
        "target": {
          "@type": "EntryPoint",
          "urlTemplate": "{{ shop.url }}/search?q={search_term_string}"
        },
        "query-input": {
          "@type": "PropertyValueSpecification",
          "valueRequired": true,
          "valueName": "search_term_string"
        }
      }
    }

    {% comment %}首頁精選內容 ItemList{% endcomment %}
    {% if template == 'index' %}
    ,
    {
      "@type": "ItemList",
      "@id": "{{ shop.url }}#featuredcontent",
      "name": "精選內容",
      "description": "NATURE MAGIC 精選產品系列與品牌故事",
      "numberOfItems": 3,
      "itemListElement": [
        {
          "@type": "ListItem",
          "position": 1,
          "item": {
            "@type": "CollectionPage",
            "name": {{ collections['grain-free-for-cats'].title | json }},
            "url": "{{ shop.url }}/collections/grain-free-for-cats"
            {% if collections['grain-free-for-cats'].image %}
            ,
            "image": {
              "@type": "ImageObject",
              "url": "{{ collections['grain-free-for-cats'].image | image_url: width: 800 | prepend: 'https:' }}",
              "width": 800,
              "height": 450
              {% if collections['grain-free-for-cats'].image.alt %}
              ,
              "caption": {{ collections['grain-free-for-cats'].image.alt | strip_html | strip_newlines | json }}
              {% endif %}
            }
            {% endif %}
          }
        },
        {
          "@type": "ListItem",
          "position": 2,
          "item": {
            "@type": "CollectionPage",
            "name": {{ collections['grain-free-for-dogs'].title | json }},
            "url": "{{ shop.url }}/collections/grain-free-for-dogs"
            {% if collections['grain-free-for-dogs'].image %}
            ,
            "image": {
              "@type": "ImageObject",
              "url": "{{ collections['grain-free-for-dogs'].image | image_url: width: 800 | prepend: 'https:' }}",
              "width": 800,
              "height": 450
              {% if collections['grain-free-for-dogs'].image.alt %}
              ,
              "caption": {{ collections['grain-free-for-dogs'].image.alt | strip_html | strip_newlines | json }}
              {% endif %}
            }
            {% endif %}
          }
        },
        {
          "@type": "ListItem",
          "position": 3,
          "item": {
            "@type": "Article",
            {% assign behind_quality_article = blogs['magic-story'].articles | where: 'handle', 'behind-the-quality' | first %}
            {% if behind_quality_article %}
            "@id": "{{ shop.url }}{{ behind_quality_article.url }}#article",
            "url": "{{ shop.url }}{{ behind_quality_article.url }}",
            "headline": {{ behind_quality_article.title | json }},
            "description": {{ behind_quality_article.excerpt_or_content | strip_html | truncate: 200 | json }},
            "datePublished": "{{ behind_quality_article.published_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
            "author": {
              "@id": "{{ shop.url }}#organization"
            }
            {% if behind_quality_article.image %}
            ,
            "image": {
              "@type": "ImageObject",
              "url": "{{ behind_quality_article.image | image_url: width: 800 | prepend: 'https:' }}",
              "width": 800,
              "height": 450
              {% if behind_quality_article.image.alt %}
              ,
              "caption": {{ behind_quality_article.image.alt | strip_html | strip_newlines | json }}
              {% endif %}
            }
            {% endif %}
            {% else %}
            "headline": "生產背景與國際認證 - NATURE MAGIC ",
            "url": "{{ shop.url }}/blogs/magic-story/behind-the-quality",
            "author": {
              "@id": "{{ shop.url }}#organization"
            }
            {% endif %}
          }
        }
      ]
    }
    {% endif %}
    {% if template.name == 'product' and product %}
    ,
    {%- liquid
      assign breadcrumb_collection = null

      if product.collections.size > 0
        assign primary_collection = null
        for collection in product.collections
          assign collection_handle = collection.handle | downcase
          if collection_handle contains 'joint-care' or collection_handle contains 'grain-free' or collection_handle contains 'subscription' or collection_handle contains 'for-cats' or collection_handle contains 'for-dogs'
            assign primary_collection = collection
            break 
          endif
        endfor
        if primary_collection == null
          assign primary_collection = product.collections.first
        endif
        assign breadcrumb_collection = primary_collection 
      endif
    -%}
    {
      "@type": "Product",
      "@id": "{{ shop.url }}{{ product.url }}#product",
      "name": {{ seo_title | json }},
      "description": {{ seo_description | strip_html | truncate: 500 | json }},
      "url": "{{ shop.url }}{{ product.url }}",
      {% if product.selected_or_first_available_variant.sku != blank %}
      "sku": "{{ product.selected_or_first_available_variant.sku }}",
      {% endif %}
      {% if product.selected_or_first_available_variant.barcode != blank %}
      "gtin": "{{ product.selected_or_first_available_variant.barcode }}",
      {% endif %}
      {% if product.featured_image %}
      "image": [
        {% for image in product.images limit: 10 %}
        {
          "@type": "ImageObject",
          "url": "{{ image | image_url: width: 1200, | prepend: 'https:' }}",
          "width": {% if image.width and image.width > 0 %}{{ image.width }}{% else %}1200{% endif %},
          "height": {% if image.height and image.height > 0 %}{{ image.height }}{% else %}630{% endif %}{% if image.alt %},
          "caption": {{ image.alt | strip_html | strip_newlines | json }}{% endif %}
        }{% unless forloop.last %},{% endunless %}
        {% endfor %}
      ],
      {% endif %}
      "brand": {
        "@type": "Brand",
        "name": {{ product.vendor | default: shop.name | default: 'NATURE MAGIC' | json }}{% if brand_alternate_names.size > 0 %},
        "alternateName": {{ brand_alternate_names_json }}{% endif %}
      },
      "manufacturer": {
        "@id": "{{ shop.url }}#organization"
      },
      {% if product.type != blank %}
      "category": {{ product.type | json }},
      {% endif %}
      "offers": {
        "@type": "Offer",
        "url": "{{ shop.url }}{{ product.url }}",
        "priceCurrency": "{{ cart.currency.iso_code }}",
        "price": "{{ product.selected_or_first_available_variant.price | divided_by: 100.0 | round: 2 }}",
        "priceValidUntil": "{{ 'now' | date: '%Y' | plus: 1 }}-12-31",
        "availability": "{% if product.selected_or_first_available_variant.available %}https://schema.org/InStock{% else %}https://schema.org/OutOfStock{% endif %}",
        "itemCondition": "https://schema.org/NewCondition",
        "hasMerchantReturnPolicy": {
          "@type": "MerchantReturnPolicy",
          "applicableCountry": "HK",
          "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow",
          "merchantReturnDays": 30,
          "returnMethod": "https://schema.org/ReturnByMail",
          "returnFees": "https://schema.org/FreeReturn"
        },
        "shippingDetails": {
          "@type": "OfferShippingDetails",
          "shippingRate": {
            "@type": "MonetaryAmount",
            "value": "0",
            "currency": "{{ cart.currency.iso_code }}"
          },
          "shippingDestination": {
            "@type": "DefinedRegion",
            "addressCountry": "HK"
          },
          "deliveryTime": {
            "@type": "ShippingDeliveryTime",
            "handlingTime": {
              "@type": "QuantitativeValue",
              "minValue": 0,
              "maxValue": 0,
              "unitCode": "d"
            },
            "transitTime": {
              "@type": "QuantitativeValue",
              "minValue": 1,
              "maxValue": 3,
              "unitCode": "d"
            }
          }
        },
        "seller": {
          "@id": "{{ shop.url }}#localbusiness"
        }
      }
      {%- liquid
        assign rating_value = product.metafields.custom.reviews_rating.value
        assign rating_count_metafield = product.metafields.custom.reviews_rating_count
        assign rating_count = blank
        if rating_count_metafield and rating_count_metafield.value != blank
          assign rating_count = rating_count_metafield.value
        elsif rating_count_metafield != blank
          assign rating_count = rating_count_metafield
        endif
        assign review_metafield = product.metafields.custom.review
        assign review_json_from_metafield = blank
        assign review_text_fallback = blank
        if review_metafield and review_metafield.value != blank
          if review_metafield.type == 'json'
            assign review_json_from_metafield = review_metafield.value | json
          else
            assign review_text_fallback = review_metafield.value | strip_html | strip_newlines
          endif
        endif
      -%}
      {% capture aggregate_rating_json %}
        {% if rating_value != blank %}
          {
            "@type": "AggregateRating",
            "ratingValue": {{ rating_value | replace: ',', '.' | times: 1 }},
            "reviewCount": {{ rating_count | default: 1 | times: 1 }},
            "bestRating": 5,
            "worstRating": 1
          }
        {% endif %}
      {% endcapture %}
      {% assign aggregate_rating_json = aggregate_rating_json | strip %}
      {% capture review_json %}
        {% if review_json_from_metafield != blank and review_json_from_metafield contains '"name"' %}
          {{ review_json_from_metafield | strip }}
        {% elsif rating_value != blank %}
          {% assign review_name = seo_title | append: ' 顧客評價' %}
          {% assign review_body_text = review_text_fallback %}
          {% if review_body_text == blank %}
            {% if rating_count != blank %}
              {% assign review_body_text = shop.name | append: ' 根據 ' | append: rating_count | append: ' 則評論的平均評分。' %}
            {% else %}
              {% assign review_body_text = shop.name | append: ' 商品顧客評價摘要。' %}
            {% endif %}
          {% endif %}
          {
            "@type": "Review",
            "name": {{ review_name | json }},
            "reviewBody": {{ review_body_text | json }},
            "reviewRating": {
              "@type": "Rating",
              "ratingValue": {{ rating_value | default: 5 | times: 1 }},
              "bestRating": 5,
              "worstRating": 1
            },
            "author": {
              "@id": "{{ shop.url }}#organization"
            },
            "itemReviewed": {
              "@type": "Product",
              "@id": "{{ shop.url }}{{ product.url }}#product",
              "name": {{ product.title | json }},
              "brand": {
                "@type": "Brand",
                "name": {{ product.vendor | default: shop.name | default: 'NATURE MAGIC' | json }}
              }
            }
          }
        {% endif %}
      {% endcapture %}
      {% assign review_json = review_json | strip %}
      {% capture product_optional_json %}
        {% if aggregate_rating_json != blank %}
          "aggregateRating": {{ aggregate_rating_json }}
        {% endif %}
        {% if review_json != blank %}
          {% if aggregate_rating_json != blank %},{% endif %}
          "review": {{ review_json }}
        {% endif %}
      {% endcapture %}
      {% assign product_optional_json = product_optional_json | strip_newlines | strip %}
      {% if product_optional_json != blank %}
      ,{{ product_optional_json }}
      {% endif %}
    }
    {% endif %}

    {% if template.name == 'collection' and collection %}
    ,
    {
      "@type": "CollectionPage",
      "@id": "{{ shop.url }}{{ collection.url }}#collectionpage",
      "url": "{{ shop.url }}{{ collection.url }}",
      "name": {{ seo_title | json }},
      {% if seo_description != blank %}
      "description": {{ seo_description | strip_html | truncate: 300 | json }},
      {% endif %}
      {% if collection.image %}
      "image": {
        "@type": "ImageObject",
        "url": "{{ collection.image | image_url: width: 1200 | prepend: 'https:' }}"{% if collection.image.alt %},
        "caption": {{ collection.image.alt | strip_html | strip_newlines | json }}{% endif %}{% if collection.image.width %},
        "width": {{ collection.image.width }}{% else %},
        "width": 1200{% endif %}{% if collection.image.height %},
        "height": {{ collection.image.height }}{% else %},
        "height": 630{% endif %}
      },
      {% endif %}
      "isPartOf": {
        "@id": "{{ shop.url }}#website"
      },
      "breadcrumb": {
        "@id": "{{ request.origin }}{{ request.path }}#breadcrumb"
      }
      ,
      "mainEntity": {
        "@type": "ItemList",
        "numberOfItems": {{ collection.products.size }},
        "itemListElement": [
          {% for product in collection.products %}
          {% render 'product-schema', product: product, position: forloop.index %}{% unless forloop.last %},{% endunless %}
          {% endfor %}
        ]
      }
    }
    {% endif %}

    {% if template.name == 'article' and article %}
    ,
    {
      "@type": "Article",
      "@id": "{{ shop.url }}{{ article.url }}#article",
      "headline": {{ seo_title | json }},
      "url": "{{ shop.url }}{{ article.url }}",
      {% if seo_description != blank %}
      "description": {{ seo_description | strip_html | truncate: 300 | json }},
      {% endif %}
      "datePublished": "{{ article.published_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
      "dateModified": "{{ article.updated_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
      "author": {
        "@id": "{{ shop.url }}#organization"
      },
      {% if article.image %}
      "image": [
        {
          "@type": "ImageObject",
          "url": "{{ article.image | image_url: width: 1200 | prepend: 'https:' }}"{% if article.image.width %},
          "width": {{ article.image.width }}{% else %},
          "width": 1200{% endif %}{% if article.image.height %},
          "height": {{ article.image.height }}{% else %},
          "height": 630{% endif %}{% if article.image.alt %},
          "caption": {{ article.image.alt | strip_html | strip_newlines | json }}{% endif %}
        }
      ],
      {% endif %}
      "mainEntityOfPage": "{{ shop.url }}{{ article.url }}",
      "isPartOf": {
        "@id": "{{ shop.url }}#website"
      }
    }
    {% comment %}其他文章列表（排除當前文章）{% endcomment %}
    {% assign other_articles_count = 0 %}
    {% for blog_article in blog.articles %}
      {% if blog_article.id != article.id %}
        {% assign other_articles_count = other_articles_count | plus: 1 %}
      {% endif %}
    {% endfor %}
    {% if other_articles_count > 0 %}
    ,
    {
      "@type": "ItemList",
      "@id": "{{ shop.url }}{{ article.url }}#otherarticles",
      "name": "其他{{ blog.title }}文章",
      "description": "{{ blog.title }}的其他精選文章",
      "numberOfItems": {{ other_articles_count }},
      "itemListElement": [
        {% assign position = 0 %}
        {% for blog_article in blog.articles %}
          {% if blog_article.id != article.id %}
            {% assign position = position | plus: 1 %}
            {% if position > 1 %},{% endif %}
        {
          "@type": "ListItem",
          "position": {{ position }},
          "item": {
            "@type": "Article",
            "@id": "{{ shop.url }}{{ blog_article.url }}#article",
            "url": "{{ shop.url }}{{ blog_article.url }}",
            "headline": {{ blog_article.title | json }},
            "description": {{ blog_article.excerpt_or_content | strip_html | truncate: 200 | json }},
            "datePublished": "{{ blog_article.published_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
            "author": {
              "@id": "{{ shop.url }}#organization"
            }
            {% if blog_article.image %}
            ,
            "image": {
              "@type": "ImageObject",
              "url": "{{ blog_article.image | image_url: width: 800 | prepend: 'https:' }}",
              "width": 800,
              "height": 450
              {% if blog_article.image.alt %}
              ,
              "caption": {{ blog_article.image.alt | strip_html | strip_newlines | json }}
              {% endif %}
            }
            {% endif %}
          }
        }
          {% endif %}
        {% endfor %}
      ]
    }
    {% endif %}
    {% endif %}

    {% if template.name == 'page' and page %}
    ,
    {
      "@type": "WebPage",
      "@id": "{{ shop.url }}{{ page.url }}#webpage",
      "url": "{{ shop.url }}{{ page.url }}",
      "name": {{ seo_title | json }},
      {% if seo_description != blank %}
      "description": {{ seo_description | strip_html | truncate: 300 | json }},
      {% endif %}
      {% if page.image %}
      "image": {
        "@type": "ImageObject",
        "url": "{{ page.image | image_url: width: 1200 | prepend: 'https:' }}"{% if page.image.alt %},
        "caption": {{ page.image.alt | strip_html | strip_newlines | json }}{% endif %}{% if page.image.width %},
        "width": {{ page.image.width }}{% else %},
        "width": 1200{% endif %}{% if page.image.height %},
        "height": {{ page.image.height }}{% else %},
        "height": 630{% endif %}
      },
      {% endif %}
      "isPartOf": {
        "@id": "{{ shop.url }}#website"
      },
      "datePublished": "{{ page.created_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
      "dateModified": "{{ page.updated_at | date: '%Y-%m-%dT%H:%M:%S%z' }}",
      "breadcrumb": {
        "@id": "{{ request.origin }}{{ request.path }}#breadcrumb"
      }
    }
    {% endif %}
    ,
    {
      "@type": "BreadcrumbList",
      "@id": "{% if template.name == 'index' %}{{ shop.url }}#breadcrumb{% else %}{{ request.origin }}{{ request.path }}#breadcrumb{% endif %}",
      "name": "網站導航路徑",
      "itemListElement": [
        {%- assign position = 1 -%}
        {
          "@type": "ListItem",
          "position": {{ position }},
          "name": {{ breadcrumb_home_label | json }},
          "item": "{{ shop.url }}"
        }
        {%- assign position = position | plus: 1 -%}

        {% if template.name == 'product' and product %}
          {% assign breadcrumb_collection = null %}
          {% if product.collections.size > 0 %}
            {% assign primary_collection = null %}
            {% comment %} 優先級判斷：精準系列優先 {% endcomment %}
            {% for collection in product.collections %}
              {% assign collection_handle = collection.handle | downcase %}
              {% if collection_handle contains 'joint-care' or collection_handle contains 'grain-free' or collection_handle contains 'subscription' or collection_handle contains 'for-cats' or collection_handle contains 'for-dogs' %}
                {% assign primary_collection = collection %}
                {% break %} 
              {% endif %}
            {% endfor %}
            {% comment %} 如果沒有精準系列，則選擇第一個集合 {% endcomment %}
            {% if primary_collection == null %}
              {% assign primary_collection = product.collections.first %}
            {% endif %}
            {% assign breadcrumb_collection = primary_collection %} 
          {% endif %}
          {% if breadcrumb_collection %}
          ,{
            "@type": "ListItem",
            "position": {{ position }},
            "name": {{ breadcrumb_collection.title | json }},
            "item": "{{ shop.url }}{{ breadcrumb_collection.url }}"
          }
          {%- assign position = position | plus: 1 -%}
          {% endif %}
          ,{
            "@type": "ListItem",
            "position": {{ position }},
            "name": {{ product.title | json }},
            "item": "{{ shop.url }}{{ product.url }}"
          }
        {% elsif template.name == 'collection' and collection %}
        ,{
          "@type": "ListItem",
          "position": {{ position }},
          "name": {{ collection.title | json }},
          "item": "{{ shop.url }}{{ collection.url }}"
        }
        {% elsif template.name == 'article' and article %}
          {% if blog %}
          ,{
            "@type": "ListItem",
            "position": {{ position }},
            "name": {{ blog.title | json }},
            "item": "{{ shop.url }}{{ blog.url }}"
          }
          {%- assign position = position | plus: 1 -%}
          {% endif %}
          ,{
            "@type": "ListItem",
            "position": {{ position }},
            "name": {{ article.title | json }},
            "item": "{{ shop.url }}{{ article.url }}"
          }
        {% elsif template.name == 'page' and page and page.handle != 'frontpage' %}
        ,{
          "@type": "ListItem",
          "position": {{ position }},
          "name": {{ page.title | json }},
          "item": "{{ shop.url }}{{ page.url }}"
        }
        {% endif %}
      ]
    }
  ]
}
</script>
